using FluentAssertions;

namespace Receipts.GeneratedTests;

public class TimestampWriterReceiptTests
{
    [Fact]
    public void SubSecondTimeAtUnixEpochRoundTrips()
    {
        DateTime value = DateTime.UnixEpoch.AddTicks(1);
        byte[] bytes = global::MessagePack.MessagePackSerializer.Serialize(value);
        DateTime result = global::MessagePack.MessagePackSerializer.Deserialize<DateTime>(bytes);
        result.Ticks.Should().Be(value.Ticks);
    }

    [Fact]
    public void WholeSecondsUseTimestamp32()
    {
        byte[] bytes = global::MessagePack.MessagePackSerializer.Serialize(DateTime.UnixEpoch.AddSeconds(1));
        bytes.Length.Should().Be(6);
    }
}

