using FluentAssertions;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class GeneratedFormatterAttributeReceiptTests
{
    [Fact]
    public async Task IgnoreMemberOnFormattedTypeIsHonoured()
    {
        string source = """
            using MessagePack;
            using MessagePack.Formatters;

            namespace Demo
            {
                [MessagePackObject]
                public class MyObject
                {
                    [Key(0)]
                    public int Kept { get; set; }

                    [IgnoreMember]
                    public int IgnoredMemberXyz { get; set; }
                }

                [GeneratedMessagePackFormatter]
                public partial class UserFormatterForMyObject : IMessagePackFormatter<MyObject> { }

                [GeneratedMessagePackResolver]
                partial class MyResolver { }
            }
            """;

        CSharpParseOptions parseOptions = new CSharpParseOptions(LanguageVersion.Latest);
        ImmutableArray<MetadataReference> framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        List<MetadataReference> references = new(framework);
        references.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));

        CSharpCompilation compilation = CSharpCompilation.Create(
            "ReceiptsAssembly",
            new[] { CSharpSyntaxTree.ParseText(source, parseOptions) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            new ISourceGenerator[] { new MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() },
            parseOptions: parseOptions);
        driver = driver.RunGenerators(compilation);
        GeneratorDriverRunResult result = driver.GetRunResult();

        SyntaxTree? formatterTree = result.GeneratedTrees.FirstOrDefault(t => t.ToString().Contains("class UserFormatterForMyObject"));
        formatterTree.Should().NotBeNull();
        formatterTree!.ToString().Should().NotContain("IgnoredMemberXyz");
    }
}
